package com.harish.student_management.entity; import jakarta.persistence.*; import lombok.*; import java.time.*; @Entity @Table(name="bus_trips") @Data @Builder @NoArgsConstructor @AllArgsConstructor public class BusTrip { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="bus_id",nullable=false) Bus bus; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="route_id",nullable=false) BusRoute route; @Column(name="started_at") LocalDateTime startedAt; @Column(name="ended_at") LocalDateTime endedAt; @Column(length=20) String status; @PrePersist void create(){if(status==null)status="PLANNED";} }
